$ErrorActionPreference = 'Stop'
opencli --profile 74u3g3us browser wt eval "(() => { const s = window.__dshWorktable && window.__dshWorktable.splitStore; if (!s || !s.active || !s.geom) return 'no-active'; const x = s.geom.right - s.chatW - 2; const y = (s.geom.top + s.geom.bottom) / 2; const el = document.elementFromPoint(x, y); const chain = []; let n = el, d = 0; while (n && d < 4) { chain.push(n.tagName + '.' + String(n.className).split(' ').slice(0, 3).join('.') + ' z=' + getComputedStyle(n).zIndex); n = n.parentElement; d++; } return JSON.stringify({ x: Math.round(x), y: Math.round(y), hit: chain }); })()"
Start-Sleep -Milliseconds 400
opencli --profile 74u3g3us browser wt eval "(() => { const s = window.__dshWorktable && window.__dshWorktable.splitStore; if (!s || !s.geom) return 'no-s'; const rects = []; const d = document.querySelector('.dsh-wt_splitDivider'); if (d) { const r = d.getBoundingClientRect(); const cx = r.left + r.width / 2; const cy = r.top + r.height / 2; const el = document.elementFromPoint(cx, cy); rects.push({ divider: [Math.round(r.left), Math.round(r.top), Math.round(r.width), Math.round(r.height)].join(','), atCenter: el && (el.classList.contains('dsh-wt_splitDivider') ? 'DIVIDER' : el.tagName + '.' + String(el.className).split(' ').slice(0, 2).join('.')) }); } return JSON.stringify({ chatW: s.chatW, right: Math.round(s.geom.right), rects }); })()"
